    mov     (0x38, sp), d0
    cmp     0, d0
    beq     loc_4841478A
    movhu   (0x30, sp), d0
    mov     IndexSwEventHandler_Table, a3
    mov     d0, a2
    asl2    d0
    mov     (d0, a3), d1
    mov     (0x50021fe8), d0
    or      d0, d1
    mov     d1, (0x50021fe8)
    mov     a2, (0x10, sp)
    mov     -1, d0
    mov     EV_SWON, d1
    call    ApPostEvent_entry, [d2], 0x1c
    mov     a2, (0x10, sp)
    mov     -1, d0
    mov     EV_SWIN, d1
    call    ApPostEvent_entry, [d2], 0x1c
    jmp     loc_48414842
loc_4841478A:
    movhu   (0x30, sp), d0
    mov     IndexSwEventHandler_Table, a3
